"""Durable source and retrieval register; rebuilds require no network."""
ASOF='2026-11-16'
sources=[]; retrievals=[]
def src(n,title,author,url,date,kind,locator,passage,note='',status='Passage inspected',origin=None):
    sid=f'S{n:03d}'; origin=origin or sid
    sources.append({'Source ID':sid,'Title':title,'Author / institution':author,'URL':url,'Publication date':date,'Access date':ASOF,'Source class':kind,'Primary / secondary':'Primary' if kind in ['Official record','Speech','Court order','Bill','Party record'] else 'Secondary','Access status':status,'Origin ID':origin,'Locator':locator,'Reliability / limitation':note or 'Supports the inspected passage; an action or proposal does not establish its outcome.','Language / geography':'English / India and international'})
    retrievals.append({'id':f'R{n:03d}','source_id':sid,'url_or_query':url,'access_date':ASOF,'route':'Canonical page or identified reproduction','access_status':status,'origin_id':origin,'locator':locator,'passage_paraphrase':passage,'method':'Web passage inspection, 15–16 November 2026','result':status,'next_action':'Reuse historical evidence; refresh current offices and litigation before later use.'})

src(1,'A/61/128: India nominates Shashi Tharoor for Secretary-General','Permanent Mission of India / United Nations','https://documents.un.org/doc/undoc/gen/n06/422/38/pdf/n0642238.pdf','2006-07-07','Official record','Letter and biography, pp.1–5','India nominated Tharoor in a 3 July letter. UN service began 1978; UNHCR Singapore head 1981–84; peacekeeping special assistant 1989–96 and Yugoslavia team lead 1991–96; communications/special projects director 1997–2001. Interim DPI head January 2001; confirmed Under-Secretary-General 1 June 2002. Fletcher PhD 1978; founding editor of Fletcher Forum. Nomination describes information-centre reform, UN Communications Group, writing and outreach.','Nomination advocacy: career facts are primary; praise and claimed effectiveness are the nominating government’s assessment. Not an independent audit of UN performance.',origin='UN-NOMINATION-2006')
src(2,'Seventeenth Lok Sabha: Members’ biographical sketches, Tharoor entry','Lok Sabha Secretariat; full PDF reproduction','https://d3u7ubx0okog7j.cloudfront.net/documents/LS_MPs_Bio_Profile_SDaZbHd.pdf',None,'Official record','PDF pp.986–988, Tharoor entry','Born 9 March 1956 in London. St Stephen’s College and Fletcher School; BA(Hons), MA, MALD, PhD. Elected Lok Sabha 2009, 2014, 2019. External Affairs MoS May 2009–18 April 2010; HRD MoS from 28 October 2012. External Affairs committee chair 1 September 2014–25 May 2019; IT chair from 13 September 2019. Lists The Great Indian Novel (1989), Riot (2001), Nehru (2003), Pax Indica (2012), among books.','Complete PDF downloaded and extracted locally with PDFKit. Historical snapshot. Profile’s 23 May 2009 ministry start conflicts with reported 28 May oath; use month precision. UN appointment chronology refined using S001.',origin='LOK-SABHA-BIO')
src(3,'Biography','Shashi Tharoor','https://shashitharoor.in/biography',None,'Speech','Biography paragraphs, lines 33–42','Describes fourth term as INC MP, current External Affairs chair and Congress Working Committee membership; nearly three decades at UN and runner-up in 2006 Secretary-General selection; writer and early social-media adopter.','Self-description. Historical IT 2019–21 / Chemicals 2021–24 dates conflict with Parliament and contemporary reporting: do not adopt those dates.',origin='THAROOR-BIO')
src(4,'Member biography, Shashi Tharoor','Digital Sansad','https://sansad.in/ls/members/biography/4569?from=members',None,'Official record','Indexed Positions Held section','Indexed text gives External Affairs chair from 26 September 2024, IT chair 13 September 2019–12 September 2022 and Chemicals chair from 13 September 2022.','Canonical page and direct download expose only an application shell. Indexed text is a lead, not passage verification. Chemicals start also conflicts with October 2022 notification reporting.',status='Search excerpt only',origin='LOK-SABHA-BIO')
src(5,'Sixteenth Report: India–Sri Lanka Relations and the Way Ahead','Standing Committee on External Affairs / Lok Sabha','https://sansad.in/getFile/app/lsscommittee/External%20Affairs/18_External_Affairs_16.pdf?source=app','2026-09-25','Official record','PDF pp.6–7, 52–61, 80–82 and 89; signed introduction','Tharoor chairs 2024–25 and 2025–26 committees and signs report 22 September 2026, presented to Speaker 25 September. Recommendations cover bilateral institutions, parliamentary exchanges, connectivity, fisheries livelihoods and maritime-boundary problems, and ITEC training.','Collective committee recommendations, not government implementation or a personal diplomatic settlement. Latest dated primary confirmation of chairmanship in this research.')
src(6,'Lok Sabha election 2009: 20 Thiruvananthapuram','Chief Electoral Officer, Kerala','https://www.ceo.kerala.gov.in/pdf/HPC-2009-RESULTS/20HPC.pdf','2009','Official record','Detailed constituency return, printed p.170','Tharoor INC 326725; P. Ramachandran Nair CPI 226727; valid votes 737641; rejected 276; total polled 737917.','Runner-up is CPI, not CPI(M). Candidate votes include postal ballots.',origin='CEO-KERALA-2009')
src(7,'General Election 2014: detailed results','Chief Electoral Officer, Kerala','https://www.ceo.kerala.gov.in/ceokerala/pdf/generalelection2014/GE_2014_DETAILED_RESULT.pdf','2014','Official record','PDF p.20, Thiruvananthapuram candidate and postal totals','Tharoor INC 297806; O. Rajagopal BJP 282336; Bennet Abraham CPI 248941; NOTA 3346; invalid 21. Seven segments: Kazhakkuttom, Vattiyoorkavu, Thiruvananthapuram, Nemom, Parassala, Kovalam, Neyyattinkara.','Downloaded PDF inspected locally. Counted denominator is sum of all candidate totals plus NOTA; invalid ballots are separate.',origin='CEO-KERALA-2014')
src(8,'Analysis of vote share and margin of victory: Lok Sabha 2019','Association for Democratic Reforms','https://adrindia.org/sites/default/files/Analysis_of_Vote_Share_Margin_Of_Victory_Lok_Sabha__2019.pdf','2019-07-18','Reference','PDF p.90, row 510; methodology p.5','Tharoor INC 416131; Kummanam Rajasekharan BJP 316142; denominator 1010180; margin 99989. Printed vote share 41.20 percent.','Independent compilation of election data. Recalculation using printed integer totals gives 41.19%, not 41.20%. Consolidated original CEO return was not retrieved; do not treat the rounded printed percentage as exact.',origin='ADR-LS2019')
src(9,'Lok Sabha 2024: candidate-wise result','Chief Electoral Officer, Kerala','https://www.ceo.kerala.gov.in/ceokerala/ceo-cms/uploads/newsupdates/ge2024-candidate-wise-results-20240606165121151554.pdf','2024-06-06','Official record','PDF p.6, constituency 20','Tharoor INC 353679 EVM + 4476 postal = 358155; Rajeev Chandrasekhar BJP 337920 + 4158 = 342078; Pannian Ravindran CPI 247648. Twelve candidate totals sum to 956230; NOTA 6753; counted including NOTA 962983.','Downloaded PDF inspected. 37.19% uses counted candidate votes plus NOTA. It differs from valid-candidate-only and all-polled denominators; the share definition is explicit.',origin='CEO-KERALA-2024')
src(10,'Congress presidential election result declaration','Madhusudan Mistry / INC Central Election Authority','https://res.cloudinary.com/dkplc2mbj/image/upload/v1666244178/Shri_Madhusudan_Mistry_19_10_2022_32ee15ebf7.pdf','2022-10-19','Party record','Result declaration, PDF p.1','Poll 17 October; count 19 October 2022. Mallikarjun Kharge 7897, Shashi Tharoor 1072, invalid 416, total 9385. Kharge declared elected under Congress constitution.','Party primary result linked by INC press conference page; vote counts do not independently adjudicate complaints about fairness.',origin='INC-PRESIDENT-2022')
src(11,'CABE meeting: RUSA and National Mission on Teachers and Teaching','Press Information Bureau / HRD Ministry','https://www.pib.gov.in/newsite/PrintRelease.aspx?relid=99978','2013-10-10','Official record','CABE proceedings paragraphs on RUSA and teachers mission','CABE noted Cabinet approval of RUSA and state planning requirements. Separately, it noted recommendations of the committee chaired by Shashi Tharoor on National Mission on Teachers and Teaching, for a scheme being launched.','Direct HTML downloaded after web cache failure. Supports committee leadership and recommendations, not sole authorship of RUSA or measured educational outcomes.')
src(12,'Anti-Discrimination and Equality Bill, 2016','Shashi Tharoor; bill reproduced by Orinam','https://orinam.net/wp-content/uploads/2017/03/SHASHI_THAROOR_BILL.pdf','2017','Bill','Contents and clauses on protected characteristics, discrimination, commissions and remedies','Private member proposal creates a broad equality framework, addresses discrimination based on protected characteristics, and proposes central/state equality commissions and remedies.','Bill title is 2016; parliamentary introduction occurred 10 March 2017 (S013). Proposed provisions are not enacted law.',origin='EQUALITY-BILL')
src(13,'MP Track: Shashi Tharoor, Sixteenth Lok Sabha','PRS Legislative Research','https://prsindia.org/mptrack/16-lok-sabha/shashitharoor',None,'Reference','Activity summary, data period and private-member-bill list','Data 1 June 2014–13 February 2019: attendance 86%, 90 debates, 481 questions. Bill list includes Equality Bill introduced 10 March 2017 and Women’s Sexual, Reproductive and Menstrual Rights Bill introduced 28 December 2018.','Counts measure recorded participation, not quality or legislation enacted; PRS compiles parliamentary records.',origin='PRS-16')
src(14,'Tharoor’s bill to decriminalise homosexuality defeated in Lok Sabha','The Indian Express','https://indianexpress.com/article/india/india-news-india/shashi-tharoors-bill-to-decriminalise-homosexuality-defeated-in-ls/','2015-12-18','Journalism','Article paragraphs on division and objections','Motion to introduce Tharoor’s Section 377 amendment defeated: 71 against, 24 for, one abstention. BJP Nishikant Dubey opposed; BJD Tathagata Satpathy supported.','Defeat at introduction, not passage followed by repeal or a judicial ruling.')
src(15,'Assessment of Tharoor’s women’s rights private member bill','The Leaflet','https://theleaflet.in/criminal-justice/shashi-tharoor-private-member-bill-criminalisation-of-marital-rape','2019-01-05','Commentary','Lines 48–58, bill purpose and Section 375 amendment','Describes Bill 255/2018 proposing women’s sexual/reproductive agency and menstrual equity, including criminalisation of marital rape and consent within marriage.','Rights-oriented commentary supports the proposed design; PDF link unavailable. Historical proposal is not a statement of present law or an enacted Tharoor reform.')
src(16,'MP Track: Shashi Tharoor, Seventeenth Lok Sabha','PRS Legislative Research','https://prsindia.org/mptrack/17-lok-sabha/shashi-tharoor',None,'Reference','Activity summary and data period','1 June 2019–10 February 2024: 93% attendance, 101 debates, 275 questions, 13 private member bills; national attendance 79%. Entries include coastal erosion, fishing harbours, rail services and Anganwadi workers.','Activity measures are descriptive. Different term lengths and database coverage constrain comparisons.',origin='PRS-17')
src(17,'MP Track: Shashi Tharoor, Eighteenth Lok Sabha','PRS Legislative Research','https://prsindia.org/mptrack/18th-lok-sabha/shashi-tharoor',None,'Reference','Activity summary, data window and debate entries','24 June 2024–13 August 2026: 89% attendance, 36 debates, 138 questions, six private member bills. Entries include coastal erosion July 2024, fisher fuel July 2024, ASHA wages March 2025, Outer Ring Road compensation/environment July 2026 and ageing population August 2026.','Snapshot stops 13 August, earlier than workbook cutoff; do not imply complete November 2026 totals.',origin='PRS-18')
src(18,'Tharoor-led panel summons Facebook','Express Web Desk / The Indian Express, with PTI','https://indianexpress.com/article/india/facebook-parliament-hate-speech-shashi-tharoor-panel-6563232/','2020-08-20','Journalism','Lines 60–80, summons and political dispute','IT committee summoned Facebook and officials for 2 September on platform misuse, citizens’ rights and women’s digital safety after allegations of selective hate-speech enforcement. BJP’s Nishikant Dubey contested Tharoor’s conduct.','Summons is a scrutiny action, not an adjudicated finding against Facebook or proof of regulatory impact.',origin='IT-FACEBOOK-2020')
src(19,'Airport privatisation: Tharoor defends his position','PTI / Times of India','https://timesofindia.indiatimes.com/india/airport-privatisation-shashi-tharoor-sticks-to-stand-says-it-will-expand-potential/articleshow/77695808.cms','2020-08-22','Journalism','Lines 119–128','Tharoor supported leasing Thiruvananthapuram airport to Adani, saying investment would expand capacity and connectivity; Left and Congress critics opposed his position. Thomas Isaac criticised the corporate-benefit argument.','Predicted benefits and criticism are attributed; not a post-privatisation causal evaluation.',origin='PTI-AIRPORT-20200822')
src(20,'One port, many claimants','Delhi Confidential / The Indian Express','https://indianexpress.com/article/delhi-confidential/delhi-confidential-1-port-many-claimants-9996998/lite/','2025-05-12','Journalism','Vizhinjam paragraph','Tharoor said Oommen Chandy asked him to seek an investor for Vizhinjam and that he urged Gautam Adani during a flight to take up the project.','Reports Tharoor’s personal credit claim, not independent confirmation of causation or sole project authorship.')
src(21,'All-party parliamentary delegations: countries and dates','Ministry of External Affairs / Lok Sabha answer annexure','https://www.mea.gov.in/Images/CPV/299-07-08-2025-LS-en.pdf','2025-08-07','Official record','Annexure 1, PDF p.3, Group 5','Group 5 leader Dr Shashi Tharoor, INC, with MPs from JMM, BJP, TDP, Shiv Sena and former ambassador; visited Guyana, Panama, Colombia, Brazil and USA, 25 May–5 June 2025.','Official itinerary documents leadership and visits; does not prove foreign governments changed policy. Outreach context corroborated in S025.')
src(22,'Congress launches professionals wing in Mumbai','PTI / Financial Express','https://www.financialexpress.com/india-news/congress-launches-professionals-wing-in-mumbai/850474/','2017-09-11','Journalism','Article body, AIPC launch and leadership','Mumbai AIPC chapter launched; wing led by Shashi Tharoor aimed to involve professionals in public affairs and connect them with Congress.','Organisational objective and launch; membership growth or electoral effect not independently measured.',origin='PTI-AIPC-20170911')
src(23,'CWC Constituted','Indian National Congress','https://inc.in/congress-sandesh/others/cwc-constituted','2023-09-16','Party record','20 August 2023 appointment notice, member list item 22','Congress president Mallikarjun Kharge constituted CWC on 20 August 2023, listing Shashi Tharoor as a member.','Party nomination, not direct public election.')
src(24,'Organisational appointments: Kerala PCC campaign committee','Indian National Congress','https://inc.in/congress-sandesh/others/organisational-appointments-14','2026-03-05','Party record','12 February 2026 press-release section, lines 35–37','Kharge appointed Ramesh Chennithala campaign committee chairman, Shashi Tharoor co-chairman and Shafi Parambil convenor for Kerala Assembly elections.','Campaign committee appointment; not an Assembly seat or chief ministership.')
src(25,'From rebel to star campaigner: Tharoor’s Congress relationship','Aneesa P. A. / ThePrint','https://theprint.in/politics/from-rebel-to-star-campaigner-how-shashi-tharoor-found-his-way-back-in-congress/2907328/','2026-04-18','Journalism','Main career and reconciliation narrative, lines 102–161','Describes G23 participation in 2020, 2022 leadership challenge, party friction over 2025 Operation Sindoor outreach and praise of government, and renewed Kerala campaigning after meeting Kharge and Rahul Gandhi. Reports criticism of coupling women’s reservation with delimitation.','Political interpretation, not proof of motives. Article contains inconsistent campaign-date sequencing; no precise rally counts or chronology inferred from it.')
src(26,'Tharoor misses Satheesan oath-taking due to Fletcher engagement','Gulam Jeelani / Mint','https://www.livemint.com/politics/news/shashi-tharoor-misses-cm-vd-satheesans-oath-taking-in-kerala-today-kerela-ministers-portfolio-rahul-gandhi-congress/amp-11779094443348.html','2026-05-18','Journalism','Lines 205–230','Reports V. D. Satheesan sworn in as Kerala CM on 18 May after UDF won 102 Assembly seats; Tharoor cited a prior Fletcher commencement commitment for absence.','State outcome is alliance-level, not a personal Tharoor election or proof his campaign caused victory. Only dated political context used.')
src(27,'India: Tharoor praised for saying Britain must pay','The World Today / Chatham House','https://www.chathamhouse.org/2015/07/india-tharoor-praised-saying-britain-must-pay','2015-07-31','Commentary','Lines 401–410','Oxford Union speech delivered 28 May 2015, uploaded 14 July; Tharoor’s tweet amplified it. Advocated moral acknowledgement of colonial harm, even token reparations; Modi praised speech.','Contemporary reception and communication analysis; not an audit of colonial economic estimates or prediction of future office.')
src(28,'Why I Am a Hindu: book review','Publishers Weekly','https://www.publishersweekly.com/9781947534568','2018-10-22','Review','Review paragraph','Praises engaging personal treatment of Hindu traditions and pluralism; finds the political second half more like campaigning and less accessible to readers outside India.','Attributed literary assessment, not neutral proof that his account exhausts Hindu traditions.')
src(29,'Why I Am a Hindu: critical review','Kancha Ilaiah Shepherd / The Indian Express','https://indianexpress.com/article/lifestyle/books/shashi-tharoor-review-why-i-am-a-hindu-5109392/lite/','2018-03-24','Review','Review, lines 18–31','Shepherd argues Tharoor’s presentation underplays caste hierarchy and spiritual inequality, and is political rather than academic.','Serious attributed critique; do not convert reviewer’s broad polemics into established fact or infer voting blocs from caste.')
src(30,'Sahitya Akademi Award 2019, Annexure A','Sahitya Akademi / PIB mirror','https://static.pib.gov.in/WriteReadData/userfiles/2.%20annexure%20A%20and%20B%20%28English%29.pdf','2019','Official record','Annexure A, English row','English award: An Era of Darkness (Non-Fiction), Shashi Tharoor.','Institutional literary recognition, not a judicial or scholarly validation of every historical argument.')
src(31,'Tharoor resigns after Congress intervention','NDTV','https://www.ndtv.com/india-news/shashi-tharoor-resigns-after-congress-says-enough-415665','2010-04-19','Journalism','Lines 224–238','Resignation accepted late 18 April amid opposition allegations that lobbying for Kochi IPL franchise involved improper benefit linked to Sunanda Pushkar’s equity; Tharoor denied wrongdoing; Pushkar relinquished stake.','Political allegations and resignation, not a conviction or a finding of corruption. Money valuations reported at the time are not independently audited here.')
src(32,'Statement in Lok Sabha after resignation','Shashi Tharoor / NDTV reproduction','https://www.ndtv.com/india-news/shashi-tharoor-statement-in-lok-sabha-415888','2010-04-20','Speech','Statement, denial and call for investigation','Tharoor denied improper financial benefit and wrongdoing, asked for a full investigation, and said resignation was to prevent embarrassment to the government.','First-person defence reproduced separately from NDTV’s event reporting; not independent exoneration.',origin='THAROOR-IPL-STATEMENT')
src(33,'State v. Shashi Tharoor: order on charge','Special Judge Geetanjali Goel / LiveLaw court-copy reproduction','https://www.livelaw.in/pdf_upload/order-on-charge-state-vs-shashi-tharoor-18082021-signed-398920.pdf','2021-08-18','Court order','SC 05/2019, FIR 04/15; pp.174–176, paragraphs 152–155','Court held material taken at face value did not establish prima facie offences under IPC 498A or 306 and discharged Tharoor. Reasoning found no instigation/aiding even assuming suicide.','Discharge before trial, not acquittal after trial. Does not establish a definitive cause of Sunanda Pushkar’s death. Reproduction of signed 176-page judicial order.',origin='SUNANDA-ORDER-20210818')
src(34,'Delhi Police challenge Tharoor’s discharge','Bar and Bench','https://www.barandbench.com/news/litigation/sunanda-pushkar-death-delhi-police-move-delhi-high-court-discharge-shashi-tharoor','2022-12-01','Journalism','Lines 35–46','Police filed revision against 2021 discharge; Delhi High Court issued notice on application to condone delay.','No later final revision disposition verified in this research; do not call the matter finally closed or imply reversal.')
src(35,'Shashi Tharoor v. State of NCT Delhi: proceedings','Supreme Court of India','https://api.sci.gov.in/supremecourt/2024/40966/40966_2024_6_35_64217_Order_15-Sep-2025.pdf','2025-09-15','Court order','SLP(Crl) 12360/2024, complete two-page proceedings','Petition concerns Delhi High Court order of 29 August 2024 in CRLMC 1394/2020. Court adjourned matter for four weeks on 15 September 2025.','Procedural adjournment; not final quashing, acquittal or conviction.',origin='SC-SCORPION-20250915')
src(36,'Supreme Court extends stay in scorpion-remark case','Express News Service / The Indian Express','https://indianexpress.com/article/india/sc-extends-stay-on-proceedings-against-shashi-tharoor-in-defamation-case-bjp-10163584/lite/','2025-08-01','Journalism','Article body on interim stay and competing arguments','Court continued stay first granted 10 September 2024. Complainant Rajeev Babbar pursued criminal defamation over 2018 remark; Tharoor said he quoted a metaphor attributed to an unnamed RSS figure in a 2012 Caravan article.','Judges’ oral suggestion to close case was not an operative final disposal. Latest inspected order is S035.')
src(37,'Rajeev Chandrashekhar v. Shashi Tharoor','Delhi High Court / Indian Kanoon reproduction','https://indiankanoon.org/doc/82603620/','2025-05-20','Court order','CRL.REV.P.187/2025, paragraphs 1–7','Order records trial court dismissal on 4 February 2025 of criminal defamation complaint; complainant challenges dismissal concerning April 2024 interviews. High Court issues notice and calls trial record, listing September 2025.','Complaint allegations and counsel’s argument are not judicial findings; later disposal not verified.',origin='DHC-RAJEEV-20250520')
src(38,'Civil defamation summons in Chandrasekhar suit','Sohini Ghosh / The Indian Express','https://indianexpress.com/article/cities/delhi/delhi-high-court-shashi-tharoor-civil-defamation-rajeev-chandrasekhar-9815104/','2025-02-03','Journalism','Lines 20–27','Delhi High Court summoned Tharoor in civil suit alleging reputational harm from purported vote-buying accusations during 2024 campaign; Chandrasekhar sought damages and injunction.','Separate civil action from S037 criminal proceedings. Summons is not liability finding; complete defence and current status not obtained.')
src(39,'Women-MP selfie caption draws criticism','PTI / New Indian Express','https://www.newindianexpress.com/nation/2021/Nov/29/tharoors-selfie-with-six-women-mps-with-attractive-place-to-work-tweet-sparks-row-2389528.html','2021-11-29','Journalism','Lines 61–74','Caption accompanying selfie with six women MPs drew objectification criticism from NCW chair Rekha Sharma and lawyer Karuna Nundy; Tharoor apologised and said the women initiated the selfie in good humour.','Criticism and response documented; not a legal finding or an inference about the women MPs’ views.',origin='PTI-SELFIE-20211129')
src(40,'Tharoor apologises for cattle-class tweet','Agencies / The Indian Express','https://indianexpress.com/article/political-pulse/tharoor-says-sorry-for-his-cattle-class-tweet/','2009-09-18','Journalism','Lines 19–31','During government/Congress austerity drive, tweet attracted party and opposition criticism; Tharoor apologised, saying expression targeted airlines’ crowding and did not express contempt for economy passengers.','Political communication controversy; no misconduct adjudication implied.')
src(41,'Congress removes Tharoor as spokesperson','Anita Katyal / Scroll','https://scroll.in/article/683578/why-the-congress-decided-to-make-an-example-of-shashi-tharoor','2014-10-14','Journalism','Lines 102–116','Sonia Gandhi accepted disciplinary recommendation removing Tharoor from AICC spokesperson list on 13 October following Kerala complaint over praise of Modi and Swachh Bharat association. He accepted decision while regretting no opportunity to answer complaint.','Formal party action distinct from party expulsion. Reporter’s explanation of leadership motives remains interpretation.')
src(42,'Fiftieth Report: Promotion of Medical Device Industry','Standing Committee on Chemicals and Fertilizers / Lok Sabha','https://sansad.in/getFile/lsscommittee/Chemicals%20%26%20Fertilizers/17_Chemicals_And_Fertilizers_50.pdf?source=loksabhadocs','2024-02-08','Official record','Composition pp.iv–vi; introduction p.vii; recommendations pp.36–56; minutes pp.61–70','Kanimozhi chaired 2021–22 committee; Tharoor chaired 2022–23 and 2023–24. Report authorised and adopted 7 February 2024 and presented 8 February. Inquiry began December 2021 and continued with evidence on 14 December 2022 and 9 October 2023.','Collective, inherited inquiry. Does not support assigning the entire inquiry or national medical-device policy to Tharoor.')
src(43,'Tharoor appointed Chemicals and Fertilizers panel chair','Express News Service / The Indian Express','https://indianexpress.com/article/india/tharoor-appointed-chairperson-parliamentary-panel-chemicals-fertilisers-8206767/','2022-10-13','Journalism','Lines 98–111','Reports Lok Sabha notification appointing Tharoor chair after Congress recommendation; annual committee allocation removed IT chairmanship from Congress.','Contemporary October appointment reporting conflicts with September in live biography. Record 2022 transition; exact effective day unresolved.')
src(44,'Congress presidential poll as a case for party renewal','Shashi Tharoor / own site reproduction of Onmanorama essay','https://shashitharoor.in/writings_my_essays_details/365','2022-10-21','Speech','Lines 37–54; linked original date','After losing, Tharoor presents contest as renewal of Congress, institutional checks against BJP dominance and stronger opposition. Acknowledges 1072 official votes; alleges uneven party pressure and irregularities while urging party unity.','Self-interpretation, not independent fairness assessment. Page header incorrectly says 15 October although text follows 19 October result; linked original path gives 21 October.',origin='THAROOR-POSTPOLL-2022')

